{
  "findings": [
    {
      "check_id": "CKV_SECRET_1",
      "title": "Hardcoded sensitive data in provider configuration",
      "resource": "provider.heroku",
      "severity": "HIGH",
      "explanation": "The 'api_key' is being sourced from a variable, but there is no validation or indication that it is securely managed. If the variable is not securely stored or encrypted, it could lead to unauthorized access to the Heroku account."
    }
  ],
  "patched_code": "provider \"heroku\" {\n  email   = \"ops@company.com\"\n  api_key = var.heroku_api_key\n}\n\nvariable \"heroku_api_key\" {\n  description = \"The API key for Heroku provider. Ensure this is securely stored and managed.\"\n  type        = string\n  sensitive   = true\n}",
  "fix_summary": "Added a 'variable' block for 'heroku_api_key' with 'sensitive = true' to ensure the API key is treated as sensitive data and to encourage secure management."
}
